(function(){var root=document.querySelector('.fx-tst'),stack=root.querySelector('.stack');
var M={ok:['&#10003;','Changes saved','Your edits to “Spring lookbook” are live.'],info:['i','Link copied','Anyone with the link can view this page.','Undo'],warn:['!','Draft moved to trash','“Untitled brief” will be deleted in 30 days.','Undo']};
function toast(k){var m=M[k],t=document.createElement('div');t.className='t '+k;
t.innerHTML='<span class="ic" aria-hidden="true">'+m[0]+'</span><div><b>'+m[1]+'</b><span>'+m[2]+'</span>'+(m[3]?'<button class="act">'+m[3]+'</button>':'')+'</div><button class="cl" aria-label="Dismiss">&#10005;</button><i class="pb"></i>';
stack.appendChild(t);while(stack.children.length>3)stack.firstChild.remove();
var left=5000,start,timer;function run(){start=Date.now();timer=setTimeout(close,left)}
function close(){clearTimeout(timer);if(!t.parentNode)return;t.classList.add('out');setTimeout(function(){t.remove()},320)}
t.addEventListener('mouseenter',function(){clearTimeout(timer);left-=Date.now()-start;t.classList.add('paused')});
t.addEventListener('mouseleave',function(){t.classList.remove('paused');run()});
t.querySelector('.cl').addEventListener('click',close);var a=t.querySelector('.act');if(a)a.addEventListener('click',close);run()}
root.querySelectorAll('[data-k]').forEach(function(b){b.addEventListener('click',function(){toast(b.dataset.k)})});toast('ok')})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
